 ctl:=population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
 SELECT * INTO STRICT q FROM population_top3000_202608_202609_v1.continuation_clear_queue_v6 WHERE clearing_id='resource:0780e264ef4ff1fee8e139d505d30ee79312ea6c7c07c57790154b3aad700024' FOR UPDATE;
 IF q.status IS DISTINCT FROM 'CLAIMED' OR q.claim_token_sha256 IS DISTINCT FROM '0ed89c8cb89afba86b3c3c378baded31e15c4a922d2f6e388d9fd157044f9781' OR q.input_sha256 IS DISTINCT FROM '0780e264ef4ff1fee8e139d505d30ee79312ea6c7c07c57790154b3aad700024' OR q.assignment_event_id IS DISTINCT FROM 51126 OR q.claim_expires_at IS NULL OR q.claim_expires_at<=clock_timestamp() OR q.not_after IS NULL OR q.not_after<=clock_timestamp() OR q.owner_id IS DISTINCT FROM ctl->>'owner_id' OR q.owner_fence IS DISTINCT FROM 3 OR q.stop_generation IS DISTINCT FROM 1 OR q.scope_sha256 IS DISTINCT FROM ctl->>'scope_sha256' OR q.assigned_executor IS DISTINCT FROM 'automation:6adc2c96db348191bca7cf4eacfdac32' OR NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=51145 AND event='ENGINEERING_CLEARING_CLAIMED_V6' AND details->>'clearing_id'=q.clearing_id) THEN RAISE EXCEPTION 'RELATION_V8_EXACT_CURRENT_CLAIM';END IF;
 SELECT * INTO STRICT a FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton;
 SELECT * INTO STRICT p FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton;
 SELECT coalesce(sum(pg_total_relation_size(oid)),0) INTO used FROM pg_class WHERE relnamespace='population_top3000_202608_202609_v1'::regnamespace AND relkind IN('r','m');
 IF population_top3000_202608_202609_v1.population_recovery_manifest_v1() IS DISTINCT FROM '{"functions":"78bba2a9159ddec989fc338c6998972dcb4cb4c02dcd0a6fe098ad802cbe79ba","adapters":"caccf5f74fc2e567f594b5b6ab7d17fb98083082cce5d630121ece4d53adc40a"}'::jsonb OR encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.resource_measured_admission_v3(text,bigint,bigint,text,uuid,jsonb,bigint)'::regprocedure),'UTF8')),'hex') IS DISTINCT FROM 'f6d4a42000f7a7ce12d3c27e53a7e5ac85c61556fbc6d592867353edaabf78e5' OR p.budget_evidence#>>'{resource_limits,max_relation_bytes}' IS DISTINCT FROM '12000000000' OR used<=10560000000 OR used>=12000000000 OR p.max_ticks<>30000 OR p.deadline IS DISTINCT FROM '2026-10-25T22:36:17.687194Z'::timestamptz OR a.max_source_bytes<>1500000000 OR a.max_provider_requests<>11900 OR a.max_http_invocations<>11955 OR a.max_dispatch_calls<>21600 THEN RAISE EXCEPTION 'RELATION_V8_EXACT_PREIMAGE_OR_TRIGGER';END IF;
 SELECT * INTO STRICT h FROM population_top3000_202608_202609_v1.continuation_handler_v6 WHERE kind='CTX02_PAGE_ADMISSION' FOR UPDATE;
 IF h.enabled IS DISTINCT FROM true OR h.function_sha256 IS DISTINCT FROM '7b68f7313f94151d9c8a5590c2b80a5fd74a6c784e5c9a5f4b6c19ceee38252e' OR h.function_sha256 IS DISTINCT FROM encode(sha256(convert_to(pg_get_functiondef(h.function_oid),'UTF8')),'hex') OR h.review_event_id IS DISTINCT FROM 50110 OR encode(sha256(convert_to(h.bounds::text,'UTF8')),'hex') IS DISTINCT FROM '5cc96c5a9801748aa0166fc94575c98599a143bd25895ef7462595a28fd71dc0' THEN RAISE EXCEPTION 'RELATION_V8_POLICY_PREIMAGE';END IF;
 proposal:=jsonb_build_object('old_max_relation_bytes',12000000000,'new_max_relation_bytes',16000000000,'old_max_source_bytes',1500000000,'new_max_source_bytes',1500000000,'probe_result_sha256','c3e971696f4f2ea13925a65a38485fbf44725e8b63b22cf798ec99908b549278','original_deadline',p.deadline::text,'successor_task_id','da79b746-8550-41c9-a6f0-3d87f4e352fd');
 nb:=jsonb_set(h.bounds,'{global_ceiling,relation_bytes}','16000000000');
 SELECT event_id INTO rv FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='RESOURCE_V3_MEASURED_ADMISSION_REVIEW' AND details->>'approved'='true' AND details->>'rollback_execution_approved'='true' AND details->>'claim_event_id'='51145' AND details->>'clearing_id'=q.clearing_id AND details->>'input_sha256'=q.input_sha256 AND details->>'proposal_sha256'=encode(sha256(convert_to(proposal::text,'UTF8')),'hex') AND details->>'probe_result_sha256'='c3e971696f4f2ea13925a65a38485fbf44725e8b63b22cf798ec99908b549278' AND details->>'handler_function_sha256'=h.function_sha256 AND details->>'handler_bounds_sha256'=encode(sha256(convert_to(nb::text,'UTF8')),'hex') AND details->>'owner_id'=ctl->>'owner_id' AND details->>'owner_fence'='3' AND details->>'stop_generation'='1' AND details->>'scope_sha256'=ctl->>'scope_sha256' AND nullif(details->>'producer','') IS NOT NULL AND nullif(details->>'reviewer','') IS NOT NULL AND details->>'producer' IS DISTINCT FROM details->>'reviewer' ORDER BY event_id DESC LIMIT 1;
 IF rv IS NULL THEN RAISE EXCEPTION 'RELATION_V8_EXACT_INDEPENDENT_REVIEW';END IF;
 b:=jsonb_build_object('a',to_jsonb(a),'p',to_jsonb(p)-'budget_evidence','budget',p.budget_evidence#-'{resource_limits,max_relation_bytes}','policy',to_jsonb(h)-ARRAY['bounds','review_event_id'],'bounds',h.bounds#-'{global_ceiling,relation_bytes}','manifest',population_top3000_202608_202609_v1.population_recovery_manifest_v1());
 ans:=population_top3000_202608_202609_v1.resource_measured_admission_v3('top3000-completion-20261024-root-5db48b32d103',3,1,q.clearing_id,'d783f5a0-54f8-4ae9-af73-8707755afb2b'::uuid,proposal,rv);
 IF ans->>'state' IS DISTINCT FROM 'ADMITTED' THEN RAISE EXCEPTION 'RELATION_V8_NATIVE_ADMISSION_REQUIRED';END IF;
 UPDATE population_top3000_202608_202609_v1.continuation_handler_v6 SET bounds=nb,review_event_id=rv WHERE kind='CTX02_PAGE_ADMISSION';
 SELECT jsonb_build_object('a',to_jsonb(aa),'p',to_jsonb(pp)-'budget_evidence','budget',pp.budget_evidence#-'{resource_limits,max_relation_bytes}','policy',to_jsonb(hh)-ARRAY['bounds','review_event_id'],'bounds',hh.bounds#-'{global_ceiling,relation_bytes}','manifest',population_top3000_202608_202609_v1.population_recovery_manifest_v1()) INTO z FROM population_top3000_202608_202609_v1.acquisition_control aa CROSS JOIN population_top3000_202608_202609_v1.pipeline_control pp CROSS JOIN population_top3000_202608_202609_v1.continuation_handler_v6 hh WHERE aa.singleton AND pp.singleton AND hh.kind='CTX02_PAGE_ADMISSION';
 IF b IS DISTINCT FROM z THEN RAISE EXCEPTION 'RELATION_V8_COUNTER_HISTORY_CODE_OTHER_BOUND_CHANGED';END IF;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('RESOURCE_RELATION_V8_POLICY_SYNC',ctl||jsonb_build_object('claim_event_id',51145,'clearing_id',q.clearing_id,'input_sha256',q.input_sha256,'useful_event_id',ans->>'useful_event_id','review_event_id',rv,'proposal',proposal,'proposal_sha256',encode(sha256(convert_to(proposal::text,'UTF8')),'hex'),'handler_bounds_sha256',encode(sha256(convert_to(nb::text,'UTF8')),'hex'),'old_relation_limit',12000000000,'new_relation_limit',16000000000,'all_other_caps_unchanged',true,'counter_history_code_unchanged',true,'effects_known',true,'family_accepted',false));
END;$relation_v8$;
$admitcode$;
BEGIN
SELECT jsonb_build_object('a',to_jsonb(a),'p',to_jsonb(p),'handler',to_jsonb(h),'manifest',population_top3000_202608_202609_v1.population_recovery_manifest_v1(),'sep22',(select to_jsonb(t)from population_top3000_202608_202609_v1.pipeline_task t where task_id='15a87469-6335-4bf6-b883-6c86315418e7'),'tasks',(select count(*)from population_top3000_202608_202609_v1.pipeline_task),'commits',(select count(*)from population_top3000_202608_202609_v1.pipeline_commit)) INTO b FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control p CROSS JOIN population_top3000_202608_202609_v1.continuation_handler_v6 h WHERE a.singleton AND p.singleton AND h.kind='CTX02_PAGE_ADMISSION';
SELECT jsonb_build_object('old_max_relation_bytes',12000000000,'new_max_relation_bytes',16000000000,'old_max_source_bytes',1500000000,'new_max_source_bytes',1500000000,'probe_result_sha256','c3e971696f4f2ea13925a65a38485fbf44725e8b63b22cf798ec99908b549278','original_deadline',deadline::text,'successor_task_id','da79b746-8550-41c9-a6f0-3d87f4e352fd') INTO proposal FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton;
INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) SELECT 'RESOURCE_V3_MEASURED_ADMISSION_REVIEW',jsonb_build_object('fixture_only',true,'approved',true,'rollback_execution_approved',true,'claim_event_id',51145,'clearing_id','resource:0780e264ef4ff1fee8e139d505d30ee79312ea6c7c07c57790154b3aad700024','input_sha256','0780e264ef4ff1fee8e139d505d30ee79312ea6c7c07c57790154b3aad700024','proposal_sha256',encode(sha256(convert_to(proposal::text,'UTF8')),'hex'),'probe_result_sha256','c3e971696f4f2ea13925a65a38485fbf44725e8b63b22cf798ec99908b549278','handler_function_sha256',h.function_sha256,'handler_bounds_sha256',encode(sha256(convert_to(jsonb_set(h.bounds,'{global_ceiling,relation_bytes}','16000000000')::text,'UTF8')),'hex'),'owner_id','top3000-completion-20261024-root-5db48b32d103','owner_fence',3,'stop_generation',1,'scope_sha256','8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd','producer','delegated-agent:/root/capacity0126','reviewer','primary-independent-review-rollback-fixture') FROM population_top3000_202608_202609_v1.continuation_handler_v6 h WHERE h.kind='CTX02_PAGE_ADMISSION' RETURNING event_id INTO rv;
BEGIN
 EXECUTE sql;
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_control p CROSS JOIN population_top3000_202608_202609_v1.continuation_handler_v6 h WHERE p.singleton AND h.kind='CTX02_PAGE_ADMISSION' AND p.budget_evidence#>>'{resource_limits,max_relation_bytes}'='16000000000' AND h.bounds#>>'{global_ceiling,relation_bytes}'='16000000000' AND h.review_event_id=rv) THEN RAISE EXCEPTION 'RELATION_V8_NATIVE_POLICY_SYNC_FAILED';END IF;checks:=checks+1;
 BEGIN EXECUTE sql; RAISE EXCEPTION 'RELATION_V8_SPENT_PREIMAGE_NOT_REJECTED';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'RELATION_V8_EXACT_PREIMAGE_OR_TRIGGER' THEN RAISE;END IF;checks:=checks+1;END;
 RAISE EXCEPTION 'RELATION_V8_POSITIVE_ROLLBACK';
EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'RELATION_V8_POSITIVE_ROLLBACK' THEN RAISE;END IF;END;
BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET owner_id='synthetic-stale-owner' WHERE singleton;EXECUTE sql;RAISE EXCEPTION 'RELATION_V8_NEGATIVE_NOT_REJECTED_owner';EXCEPTION WHEN OTHERS THEN IF SQLERRM IS DISTINCT FROM 'CONTINUATION_OWNER_STOP_SCOPE_CHANGED' THEN RAISE;END IF;checks:=checks+1;END;
BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET stopped=true WHERE singleton;EXECUTE sql;RAISE EXCEPTION 'RELATION_V8_NEGATIVE_NOT_REJECTED_stop';EXCEPTION WHEN OTHERS THEN IF SQLERRM IS DISTINCT FROM 'CONTINUATION_USER_OR_CONTROL_HOLD' THEN RAISE;END IF;checks:=checks+1;END;
BEGIN DELETE FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=rv;EXECUTE sql;RAISE EXCEPTION 'RELATION_V8_NEGATIVE_NOT_REJECTED_review';EXCEPTION WHEN OTHERS THEN IF SQLERRM IS DISTINCT FROM 'RELATION_V8_EXACT_INDEPENDENT_REVIEW' THEN RAISE;END IF;checks:=checks+1;END;
BEGIN UPDATE population_top3000_202608_202609_v1.continuation_handler_v6 SET review_event_id=1 WHERE kind='CTX02_PAGE_ADMISSION';EXECUTE sql;RAISE EXCEPTION 'RELATION_V8_NEGATIVE_NOT_REJECTED_policy';EXCEPTION WHEN OTHERS THEN IF SQLERRM IS DISTINCT FROM 'RELATION_V8_POLICY_PREIMAGE' THEN RAISE;END IF;checks:=checks+1;END;
BEGIN UPDATE population_top3000_202608_202609_v1.continuation_clear_queue_v6 SET claim_expires_at='2000-01-01T00:00:00Z' WHERE clearing_id='resource:0780e264ef4ff1fee8e139d505d30ee79312ea6c7c07c57790154b3aad700024';EXECUTE sql;RAISE EXCEPTION 'RELATION_V8_NEGATIVE_NOT_REJECTED_claim';EXCEPTION WHEN OTHERS THEN IF SQLERRM IS DISTINCT FROM 'RELATION_V8_EXACT_CURRENT_CLAIM' THEN RAISE;END IF;checks:=checks+1;END;
BEGIN UPDATE population_top3000_202608_202609_v1.resource_probe_v3 SET result=jsonb_set(result,'{observed_at}',to_jsonb('2000-01-01T00:00:00Z'::text)) WHERE probe_id='d783f5a0-54f8-4ae9-af73-8707755afb2b';EXECUTE sql;RAISE EXCEPTION 'RELATION_V8_NEGATIVE_NOT_REJECTED_probe';EXCEPTION WHEN OTHERS THEN IF SQLERRM IS DISTINCT FROM 'RESOURCE_V3_FRESH_MEASUREMENT_REQUIRED' THEN RAISE;END IF;checks:=checks+1;END;
BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET max_provider_requests=11899 WHERE singleton;EXECUTE sql;RAISE EXCEPTION 'RELATION_V8_NEGATIVE_NOT_REJECTED_othercap';EXCEPTION WHEN OTHERS THEN IF SQLERRM IS DISTINCT FROM 'RELATION_V8_EXACT_PREIMAGE_OR_TRIGGER' THEN RAISE;END IF;checks:=checks+1;END;
BEGIN UPDATE population_top3000_202608_202609_v1.pipeline_task SET status='LEASED' WHERE task_id='da79b746-8550-41c9-a6f0-3d87f4e352fd';EXECUTE sql;RAISE EXCEPTION 'RELATION_V8_NEGATIVE_NOT_REJECTED_quiet';EXCEPTION WHEN OTHERS THEN IF SQLERRM IS DISTINCT FROM 'RELATION_V8_QUIET_WORK_REQUIRED' THEN RAISE;END IF;checks:=checks+1;END;
SELECT jsonb_build_object('a',to_jsonb(a),'p',to_jsonb(p),'handler',to_jsonb(h),'manifest',population_top3000_202608_202609_v1.population_recovery_manifest_v1(),'sep22',(select to_jsonb(t)from population_top3000_202608_202609_v1.pipeline_task t where task_id='15a87469-6335-4bf6-b883-6c86315418e7'),'tasks',(select count(*)from population_top3000_202608_202609_v1.pipeline_task),'commits',(select count(*)from population_top3000_202608_202609_v1.pipeline_commit)) INTO z FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control p CROSS JOIN population_top3000_202608_202609_v1.continuation_handler_v6 h WHERE a.singleton AND p.singleton AND h.kind='CTX02_PAGE_ADMISSION';
IF b IS DISTINCT FROM z THEN RAISE EXCEPTION 'RELATION_V8_CONTROLS_POLICY_MANIFEST_HISTORY_NOT_RESTORED';END IF;checks:=checks+1;
PERFORM set_config('top3000.relation_v8_proof',jsonb_build_object('result','PASS_RELATION_ONLY_12_TO16GB_ROLLBACK','checks',checks,'assignment_event_id',51126,'claim_event_id',51145,'sql_sha256',encode(sha256(convert_to(sql,'UTF8')),'hex'),'probe_result_sha256','c3e971696f4f2ea13925a65a38485fbf44725e8b63b22cf798ec99908b549278','installed_native_helper_used',true,'control_budget_policy_manifest_taskcount_commitcount_sep22_preserved',true,'production_capacity_changed',false,'source_calls',0)::text,true);
END;$test$;
$testcode$;
